fn put64(out:[*]u8,pos:usize,x:i64)void{const u:u64=@bitCast(x);for(0..8)|j|out[pos+j]=@truncate(u>>(8*j));}
fn narrow(x:i64)i16{return @truncate(x);}
fn line(d:*[64]i16,base:usize,k:usize,m:u6,n:u6,r:*const [12]i16)void{var t=[_]i64{0}**12;for(0..4)|j|{t[j]=@as(i64,d[base+k*j])+d[base+k*(7-j)];t[7-j]=@as(i64,d[base+k*j])-d[base+k*(7-j)];}t[8]=t[0]+t[3];t[9]=t[0]-t[3];t[10]=t[1]+t[2];t[11]=t[1]-t[2];d[base]=narrow((t[8]+t[10])>>m);d[base+4*k]=narrow((t[8]-t[10])>>m);t[8]=@as(i64,@as(i16,@truncate(t[11]+t[9])))*r[10];d[base+2*k]=narrow(t[8]+@as(i16,@truncate((t[9]*r[9])>>n)));d[base+6*k]=narrow(t[8]+@as(i16,@truncate((t[11]*r[11])>>n)));t[0]=@as(i64,@as(i16,@truncate(t[4]+t[7])))*r[2];t[1]=@as(i64,@as(i16,@truncate(t[5]+t[6])))*r[0];t[2]=t[4]+t[6];t[3]=t[5]+t[7];t[8]=@as(i64,@as(i16,@truncate(t[2]+t[3])))*r[8];t[2]=@as(i64,@as(i16,@truncate(t[2])))*r[1]+t[8];t[3]=@as(i64,@as(i16,@truncate(t[3])))*r[3]+t[8];d[base+7*k]=narrow(@as(i16,@truncate(t[4]*r[4]+t[0]+t[2]))>>n);d[base+5*k]=narrow(@as(i16,@truncate(t[5]*r[6]+t[1]+t[3]))>>n);d[base+3*k]=narrow(@as(i16,@truncate(t[6]*r[5]+t[1]+t[2]))>>n);d[base+k]=narrow(@as(i16,@truncate(t[7]*r[7]+t[0]+t[3]))>>n);}
pub export fn edn_jpeg_dct(raw:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{const v=raw orelse return -1;if(n!=76)return -1;var d=[_]i16{0}**64;var r=[_]i16{0}**12;for(0..64)|i|{if(v[i]< -8 or v[i]>8)return -1;d[i]=@intCast(v[i]);}for(0..12)|i|{if(v[64+i]< -32 or v[64+i]>31)return -1;r[i]=@intCast(v[64+i]);}const o=out orelse return -2;if(cap<512)return -2;for(0..8)|row|line(&d,row*8,1,0,13,&r);for(0..8)|col|line(&d,col,8,3,16,&r);for(0..64)|i|put64(o,8*i,d[i]);return 512;}
